package com.example.discussions.dto;
import com.example.discussions.model.*;import java.time.Instant;import java.util.List;
public final class Responses {private Responses(){}public record Auth(String token,User user){}public record ReactionView(String emoji,long count,boolean reactedByMe){}public record CommentView(Long id,String body,User author,Instant createdAt,long voteCount,boolean votedByMe,List<ReactionView> reactions,List<CommentView> replies){}public record DiscussionView(Long id,String title,String body,String status,User author,Category category,long voteCount,long commentCount,boolean votedByMe,List<ReactionView> reactions,Instant createdAt,Instant updatedAt,List<CommentView> comments){public static DiscussionView of(Discussion d,long votes,boolean mine){return new DiscussionView(d.id,d.title,d.body,d.status.name(),d.author,d.category,votes,d.comments.size(),mine,List.of(),d.createdAt,d.updatedAt,List.of());}}public record Profile(Long id,String username,String displayName,String bio,String role,Instant createdAt,List<DiscussionView> discussions){} }
